export type UUID=string;
export interface SourceVersion{shopRevision:number;authorityEpoch:number;financialRevision:number}
export type CostEvidence={kind:'exact';minor:number}|{kind:'bounded';lowerMinor:number;upperMinor:number;reason:string}|{kind:'unknown';reason:string};
export interface PriceObservation{id:UUID;shopId:UUID;itemName:string;packLabel:string;usablePack:{amount:{numerator:number;denominator:number};unit:'count'|'gram'|'kilogram'|'ounce'|'pound'|'milliliter'|'liter'|'fluidOunce'|'cup';originalLiteral:string}|null;price:CostEvidence;currency:'USD';store:string;branch:string;channel:'storeShelf'|'warehouse'|'retailerWebsite'|'retailerApp'|'other'|'unspecified';mode:'pickup'|'delivery'|'inStore';eligibility:string;observedAt:string;sourceText:string;sourceLocale:string}
export interface FinancialEntry{id:UUID;evidenceKey:UUID;kind:'postedCharge'|'postedTopUp'|'pendingCredit'|'postedCredit'|'includedCredit'|'paymentHold'|'holdRelease';amountMinor:number;currency:'USD';occurredAt:string;creditId:UUID|null;chargeEvidenceKey:UUID|null;holdEvidenceKey:UUID|null;sourceText:string}
export interface FinancialPage{shopId:UUID;sourceVersion:SourceVersion;evidenceSource:'shopper_reported';entries:FinancialEntry[];nextCursor:UUID|null}
export interface FinancialAppend{clientKey:UUID;sourceVersion:SourceVersion;entry:FinancialEntry}
export interface FinancialAppendReceipt{entryId:UUID;shopId:UUID;sourceVersion:SourceVersion;recorded:true;evidenceSource:'shopper_reported'}
export interface FinancialReview{clientKey:UUID;sourceVersion:SourceVersion;allEvidenceEntered:boolean;closeShop:boolean}
export interface FinancialReviewReceipt{reviewId:UUID;shopId:UUID;sourceVersion:SourceVersion;reviewedAt:string;allEvidenceEntered:boolean;appShopClosed:boolean;reconciledEntered:boolean}
export interface MoneyRange{lowerMinor:number;upperMinor:number|null}
export interface ShopBudgetSummary{shopId:UUID;sourceVersion:SourceVersion;currency:'USD';postedNetMinor:number;pendingCreditsMinor:number;includedCreditsMinor:number;paymentHoldsMinor:number;expectedUnpaid:MoneyRange;projectedCommitment:MoneyRange;reconciledEntered:boolean}
export interface PermittedSubtotal{shops:ShopBudgetSummary[];currency:'USD';postedNetMinor:number;pendingCreditsMinor:number;includedCreditsMinor:number;paymentHoldsMinor:number;expectedUnpaid:MoneyRange;projectedCommitment:MoneyRange}
export interface FutureReservation{id:UUID;originalText:string;amountMinor:number;plannedAt:string;state:{kind:'reserved'}|{kind:'released'}|{kind:'applied';shopId:UUID}}
export interface BudgetPeriod{id:UUID;title:string;startsAt:string;endsAt:string;timeZoneId:string;currency:'USD';shopBudgetMinor:number;alreadyExcludedReserveMinor:number|null;shopIds:UUID[];reservations:FutureReservation[];reviewedCompleteAt:string|null}
export interface PeriodWrite{clientKey:UUID;baseRevision:number;period:BudgetPeriod}
export interface PeriodReceipt{periodId:UUID;revision:number;saved:true}
export type PeriodResponse={permitted:PermittedSubtotal}|{periodId:UUID;revision:number;period:BudgetPeriod;permitted:PermittedSubtotal;futureReservedMinor:number;remaining:{minimumMinor:number|null;maximumMinor:number};reconciledEnteredPeriod:boolean};
export interface ObservationWrite{clientKey:UUID;observation:PriceObservation}
export interface PriceObservationPage{observations:PriceObservation[];nextCursor:UUID|null}
export interface BudgetPeriodPage{periods:{periodId:UUID;revision:number;updatedAt:string}[];nextCursor:UUID|null}
export interface SavedBudgetPeriod{periodId:UUID;revision:number;period:BudgetPeriod}
